VAR CurrentValue =
			    SWITCH (
			        TRUE (),
			        SELECTEDVALUE ( 'P_ABC_銷售額'[P_ABC_銷售額 個欄位] ) = "'Measure'[銷售額 MTD]", 'Measure'[銷售額 MTD],
			        SELECTEDVALUE ( 'P_ABC_銷售額'[P_ABC_銷售額 個欄位] ) = "'Measure'[銷售額 YTD]", 'Measure'[銷售額 YTD],
			        SELECTEDVALUE ( 'P_ABC_銷售額'[P_ABC_銷售額 個欄位] ) = "'Measure'[銷售額 近12月]", 'Measure'[銷售額 近12月]
			    )
			VAR vTable =
			    CALCULATETABLE (
			        ADDCOLUMNS (
			            VALUES ( D_Product[Assay] ),
			            "Sales",
			                SWITCH (
			                    TRUE (),
			                    SELECTEDVALUE ( 'P_ABC_銷售額'[P_ABC_銷售額 個欄位] ) = "'Measure'[銷售額 MTD]", 'Measure'[銷售額 MTD],
			                    SELECTEDVALUE ( 'P_ABC_銷售額'[P_ABC_銷售額 個欄位] ) = "'Measure'[銷售額 YTD]", 'Measure'[銷售額 YTD],
			                    SELECTEDVALUE ( 'P_ABC_銷售額'[P_ABC_銷售額 個欄位] ) = "'Measure'[銷售額 近12月]", 'Measure'[銷售額 近12月]
			                )
			        ),
			        ALLSELECTED ()
			    ) // var CurrentValue = 
			// SWITCH(
			//     TRUE(),
			//     SELECTEDVALUE('P_ABC_銷售額'[P_ABC_銷售額 個欄位]) ="'Measure'[ABC_銷售額 MTD 按維度]",'Measure'[ABC_銷售額 MTD 按維度],
			//     SELECTEDVALUE('P_ABC_銷售額'[P_ABC_銷售額 個欄位]) ="'Measure'[ABC_銷售額 YTD 按維度]",'Measure'[ABC_銷售額 YTD 按維度],
			//     SELECTEDVALUE('P_ABC_銷售額'[P_ABC_銷售額 個欄位]) ="'Measure'[ABC_銷售額 近12月 按維度]",'Measure'[ABC_銷售額 近12月 按維度]
			// )
			// var vTable = 
			// CALCULATETABLE(
			//     ADDCOLUMNS( VALUES( V_Assay[Assay]) , "Sales",SWITCH(
			//     TRUE(),
			//     SELECTEDVALUE('P_ABC_銷售額'[P_ABC_銷售額 個欄位]) ="'Measure'[ABC_銷售額 MTD 按維度]",'Measure'[ABC_銷售額 MTD 按維度],
			//     SELECTEDVALUE('P_ABC_銷售額'[P_ABC_銷售額 個欄位]) ="'Measure'[ABC_銷售額 YTD 按維度]",'Measure'[ABC_銷售額 YTD 按維度],
			//     SELECTEDVALUE('P_ABC_銷售額'[P_ABC_銷售額 個欄位]) ="'Measure'[ABC_銷售額 近12月 按維度]",'Measure'[ABC_銷售額 近12月 按維度]
			// )),
			//     ALLSELECTED())
			RETURN
			    DIVIDE (
			        SUMX ( FILTER ( vTable, [Sales] >= CurrentValue ), [Sales] ),
			        SUMX ( vTable, [Sales] )
			    )

