			VAR CustomerColor =
			    SWITCH (
			        TRUE (),
			        [近N月無銷量的客戶] + [連續3次銷量下降 GroupByCustomer] >= 1,
			            "#14D2FF" // [近N月無銷量的客戶] >=1 &&  [連續3次銷量下降 GroupByCustomer] >= 1 , "#1476F9",
			            // [近N月無銷量的客戶] >=1, "#14A1F8" , 
			            // [連續3次銷量下降 GroupByCustomer] >= 1, "#14D2FF"
			    )
			VAR AssayColor =
			    SWITCH (
			        TRUE (),
			        MAX ( D_Product[New_Assay_Code] ) + MAX ( D_Product[Key_Assay_Code] ) >= 1,
			            "#14D2FF" // MAX(D_Product[New_Assay_Code]) >= 1 && MAX(D_Product[Key_Assay_Code]) >= 1,"#1476F9",
			            // MAX(D_Product[New_Assay_Code]) >= 1,"#14A1F8",
			            // MAX(D_Product[Key_Assay_Code]) >= 1,"#14D2FF"
			    )
			VAR CurrentDim =
			    SELECTEDVALUE ( 'P_ABC_維度'[P_ABC_維度 個欄位] )
			RETURN
			    SWITCH (
			        TRUE (),
			        // CurrentDim = "'D_Region'[省份]", "#1476F9",
			        CurrentDim = "'D_Customer'[Customer_Name]", CustomerColor,
			        CurrentDim = "'D_Product'[Assay]", AssayColor
			    )
